import org.junit.Test;
import static org.junit.Assert.*;
import java.io.File;
import java.io.FileWriter;
import java.io.IOException;
import java.util.HashMap;
import java.util.Locale;

public class EpubCheckerTest {

    @Test
    public void getLocale_ReturnsCorrectLocale() {
        Locale locale = new EpubChecker().getLocale();
        assertEquals(Locale.ENGLISH, locale);
    }

    @Test
    public void getLocale_ReturnsNullWhenLocaleIsUndefined() {
        new EpubChecker().setLocale(null);
        assertNull(new EpubChecker().getLocale());
    }

    @Test
    public void run_ValidEpubFileReturnsZeroErrors() throws IOException {
        File file = new File("valid.epub");
        int errors = new EpubChecker().run(new String[] {"-f", file.getAbsolutePath()});
        assertEquals(0, errors);
    }

    @Test
    public void run_InvalidEpubFileReturnsNonZeroErrors() throws IOException {
        File file = new File("invalid.epb");
        int errors = new EpubChecker().run(new String[] {"-f", file.getAbsolutePath()});
        assertTrue(errors > 0);
    }

    @Test
    public void validateFile_ValidFileReturnsZeroErrors() {
        Report report = mock(Report.class);
        EPUBProfile profile = mock(EPUBProfile.class);
        int errors = new EpubChecker().validateFile("valid.epub", EPUBVersion.V1_3, report, profile);
        assertEquals(0, errors);
    }

    @Test
    public void validateFile_InvalidFileReturnsNonZeroErrors() {
        Report report = mock(Report.class);
        EPUBProfile profile = mock(EPUBProfile.class);
        int errors = new EpubChecker().validateFile("invalid.epb", EPUBVersion.V1_3, report, profile);
        assertTrue(errors > 0);
    }
}
